<div class="page-head"><div><div class="small-caps">Catalogue interne</div><h2>Produits</h2><p><?=e($total)?> références actives · prix, stock, catégories et codes-barres.</p></div><div class="quick-actions"><a class="btn btn-soft" href="<?=e(base_url('products/export'))?>">⇩ Exporter CSV</a><button class="btn btn-soft" data-bs-toggle="modal" data-bs-target="#importModal">⇧ Importer CSV</button><a class="btn btn-km" href="<?=e(base_url('products/create'))?>">+ Nouveau produit</a></div></div>
<div class="km-card p-3"><form class="row g-2 mb-3" method="get"><div class="col-md-6"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Rechercher par nom, code interne ou code-barres"></div><div class="col-md-4"><select class="form-select" name="category"><option value="">Toutes catégories</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=selected($category,$c['id'])?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-dark w-100">Rechercher</button></div></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Code</th><th>Produit</th><th>Catégorie</th><th>Prix</th><th>Stock disponible</th><th>Statut</th><th></th></tr></thead><tbody><?php foreach($items as $p):?><tr><td><code><?=e($p['internal_code'])?></code></td><td><div class="d-flex align-items-center gap-3"><img src="<?=e(product_image_url($p))?>" style="width:48px;height:48px;object-fit:cover;border-radius:13px" alt=""><div><strong><?=e($p['name'])?></strong><div class="small text-muted"><?=e($p['barcode'])?></div></div></div></td><td><span class="badge badge-soft-dark"><?=e($p['category'])?></span></td><td><strong><?=money($p['sale_price'])?></strong></td><td class="<?=((float)$p['available_qty']<=(float)$p['min_stock'])?'low':'ok'?>"><?=e($p['available_qty'])?> <?=e($p['unit'])?></td><td><span class="badge <?=$p['status']==='ACTIVE'?'badge-soft-success':'badge-soft-dark'?>"><?=e($p['status'])?></span></td><td class="text-end"><a class="btn btn-sm btn-soft" href="<?=e(base_url('products/'.$p['id'].'/edit'))?>">Modifier</a></td></tr><?php endforeach;?></tbody></table></div><nav class="mt-3"><ul class="pagination mb-0"><?php for($i=1;$i<=$pages;$i++):?><li class="page-item <?=$i===$page?'active':''?>"><a class="page-link" href="?q=<?=urlencode($q)?>&category=<?=urlencode((string)$category)?>&page=<?=$i?>"><?=$i?></a></li><?php endfor;?></ul></nav></div>
<div class="modal fade" id="importModal" tabindex="-1"><div class="modal-dialog"><div class="modal-content border-0 rounded-4"><div class="modal-header"><h5 class="modal-title fw-800">Importer des produits</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><form method="post" enctype="multipart/form-data" action="<?=e(base_url('products/import'))?>"><?=csrf_field()?><div class="modal-body"><p class="small text-muted">CSV séparé par point-virgule. Colonnes minimales : internal_code, name, category, purchase_price, sale_price. Les colonnes barcode, brand, unit, quantity, min_stock, max_stock, location, expiration_date et status sont facultatives.</p><input class="form-control" type="file" name="csv" accept=".csv,text/csv" required></div><div class="modal-footer"><button class="btn btn-km">Importer le fichier</button></div></form></div></div></div>
